import{_ as a,o,c as t,a3 as i}from"./chunks/framework.DAK02U1-.js";const m=JSON.parse('{"title":"What is xclang?","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"What is xclang? | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/guide/what-is-xclang"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/guide/what-is-xclang"}]]},"headers":[],"relativePath":"xclang/guide/what-is-xclang.md","filePath":"en/xclang/guide/what-is-xclang.md","lastUpdated":1794509097000}'),r={name:"xclang/guide/what-is-xclang.md"};function n(s,e,l,c,d,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="what-is-xclang" tabindex="-1">What is xclang? <a class="header-anchor" href="#what-is-xclang" aria-label="Permalink to &quot;What is xclang?&quot;">​</a></h1><p>xclang is a clang toolchain for cross-compiling: one compiler for every target. One directory holds the compiler, the linker, the binary tools, and the <em>sysroot</em> (the C library&#39;s headers and libraries) and prebuilt runtimes for eight targets. Cross-compiling is a <code>--target</code> flag and nothing else:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">clang++</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --target=aarch64-w64-mingw32</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.cpp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello.exe</span></span></code></pre></div><h2 id="what-is-in-a-release" tabindex="-1">What Is in a Release <a class="header-anchor" href="#what-is-in-a-release" aria-label="Permalink to &quot;What Is in a Release&quot;">​</a></h2><ul><li><strong>clang, lld and the LLVM binary tools</strong>, built from stock LLVM with a few <a href="./../reference/patches">patches</a> on their way upstream, packaged as one multicall program (<code>llvm</code>) and linked statically against xclang&#39;s own <code>libc++</code> for six hosts (<a href="./../design/toolchain">toolchain structure</a>).</li><li><strong>Eight targets in every archive</strong>: <a href="./cross-compiling#linux">Linux</a> x64 and arm64 (glibc 2.17, and musl 1.2.6 for static programs), <a href="./cross-compiling#windows">Windows</a> x64 and arm64 (MinGW-w64 with UCRT), and <a href="./cross-compiling#macos">macOS</a> arm64 and x64. Each target has its sysroot, <code>libc++</code>, <code>libc++abi</code>, <code>libunwind</code> and <code>compiler-rt</code>, prebuilt, and a config file that points <code>clang</code> at them (<a href="./cross-compiling">cross-compiling</a>).</li><li><strong>The MSVC targets</strong>, Windows x64 and arm64 with Microsoft&#39;s CRT and xclang&#39;s <code>libc++</code> (or Microsoft&#39;s STL), from every host, against the SDK that the <code>xclang</code> command fetches from Microsoft or an installed Visual Studio on Windows (<a href="./cross-compiling#windows">Windows</a>, <a href="./../design/windows">Windows design</a>).</li><li><strong>The <code>xclang</code> command</strong>: it fetches the Apple and Microsoft SDKs that no one may redistribute, and <code>xclang cargo</code> builds Rust for xclang&#39;s targets with no cargo config (<a href="./../reference/xclang-command">the <code>xclang</code> command</a>, <a href="./../integrations/cargo">Rust and Cargo</a>).</li><li><strong>A CMake package and a Bazel module</strong>, for the host or any target, with <code>import std</code> built for the build (<a href="./../integrations/cmake">CMake</a>, <a href="./../integrations/bazel">Bazel</a>).</li><li><strong>The runtimes&#39; sources</strong>, which the CMake package and the Bazel module build on demand for MemorySanitizer and for <code>libc++</code>&#39;s hardening and ABI options, for every target but the MSVC ones (<a href="./../features/runtimes-from-source">runtimes from source</a>).</li><li><strong>libclang</strong>: the static libraries and headers of <code>clang</code> and LLVM that the release was built from, for tools built on <code>clang</code> (<a href="./../features/libclang">libclang</a>).</li></ul><p>Targets and features that no release has yet are in the <a href="./../design/roadmap">roadmap</a>.</p><h2 id="what-it-does-for-a-build" tabindex="-1">What It Does for a Build <a class="header-anchor" href="#what-it-does-for-a-build" aria-label="Permalink to &quot;What It Does for a Build&quot;">​</a></h2><p>A C++ build is <em>hermetic</em> when its output depends only on its declared inputs: the same sources and toolchain give the same program on any machine and in any directory. That is what xclang is built for.</p><ul><li><strong>Reproducible.</strong> A release is never replaced: a rebuild is the next revision. The Bazel module and CMake download check every archive by its <code>sha256</code>. In Bazel builds, no command line or debug information holds an absolute path except for Xcode&#39;s macOS SDK, so a build in a second checkout produces the same bytes (<a href="./../design/bazel-module">the Bazel module</a>).</li><li><strong>Portable programs.</strong> A program depends at run time only on the system libraries every installation of its OS has: glibc 2.17 or later on <a href="./cross-compiling#linux">Linux</a> (or nothing with musl), <a href="./cross-compiling#windows">Windows 10</a> or later, or <a href="./cross-compiling#macos">macOS 13</a> or later. <code>libc++</code> and the other runtimes are linked in, and build scripts written for GCC (<code>-latomic</code>, <code>-lgcc_s</code>, <code>-lstdc++</code>) link unchanged (<a href="./../design/hermeticity">hermeticity</a>).</li><li><strong>One compiler for every target.</strong> <code>clang</code> compiles for every LLVM target, and xclang ships the target libraries beside it. Selecting a target takes only <code>--target=&lt;triple&gt;</code>, and a compiler upgrade applies to all targets at once (<a href="./cross-compiling">cross-compiling</a>).</li><li><strong>Correct build caches.</strong> With a compiler taken from the machine, a new compiler version leaves a build cache serving objects from the old one. In Bazel, every toolchain file that an action reads is a declared input, so a new release rebuilds what it should, and module files are inputs of their importers (<a href="./../design/bazel-module">the Bazel module</a>, <a href="./../features/modules">C++20 modules</a>).</li><li><strong>C++20 modules.</strong> A module file is usable only by importers compiled with the same language options, so a prebuilt <code>std</code> module cannot be shipped. xclang compiles <code>libc++</code>&#39;s <code>std</code> and <code>std.compat</code> modules for each build with its options, as <code>xclang::std</code> in CMake without experimental switches and <code>@xclang//bazel:std</code> in Bazel (<a href="./../features/modules">C++20 modules</a>).</li><li><strong>Fast.</strong> <code>clang</code> and <code>lld</code> are built with PGO and ThinLTO on every host, trained on compiling real C and C++ code, precompiled headers, C++20 modules and code completion (<a href="./../design/pgo">PGO</a>). <code>libclang</code> ships as ThinLTO bitcode, and the ThinLTO cache reduces relinks of tools built on it to seconds (<a href="./../features/libclang">libclang</a>).</li><li><strong>Correctness tools.</strong> xclang ships sanitizer runtimes along with an ASan build of <code>libc++</code> that prevents false container-overflow reports (<a href="./../features/sanitizers">sanitizers</a>), and builds the runtimes from source for MemorySanitizer (<a href="./../features/runtimes-from-source">runtimes from source</a>). Debug symbols come apart from the program: GSYM files, the same on every run, for every target but the MSVC ones, which have PDBs, and dSYMs for macOS (<a href="./../features/debugging">debugging</a>).</li><li><strong>Supply chain.</strong> Every archive is listed in <code>SHA256SUMS</code>, built from LLVM&#39;s release tarball with documented <a href="./../reference/patches">patches</a>, made twice on two machines and compared byte for byte, and packaged with its components&#39; licenses and an SPDX document (<a href="./../reference/releases">releases</a>, <a href="./../reference/layout">archive layout</a>). Vendor SDKs are never in an archive; you fetch them from the vendor, pinned by version and <code>sha256</code> (<a href="./../reference/xclang-command">the <code>xclang</code> command</a>).</li><li><strong>One toolchain for every build.</strong> The same toolchain directory serves <a href="./../integrations/clang">plain clang, Make and Meson</a>, <a href="./../integrations/cmake">CMake</a>, <a href="./../integrations/bazel">Bazel</a>, and <a href="./../integrations/cargo">cargo</a>, from pixi, an archive, FetchContent or the Bazel registry (<a href="./quick-start">quick start</a>).</li></ul><h2 id="who-it-is-for" tabindex="-1">Who It Is For <a class="header-anchor" href="#who-it-is-for" aria-label="Permalink to &quot;Who It Is For&quot;">​</a></h2><ul><li><strong>Projects that ship programs</strong> to user machines: command-line tools, language servers and build tools that run as a single file without a redistributable or Homebrew.</li><li><strong>CI that builds for several targets</strong> from one runner OS, with one compiler version for all of them (<a href="./../integrations/ci">CI</a>).</li><li><strong>Teams that pin one toolchain</strong> across developer machines and CI, in CMake, Bazel and plain commands.</li><li><strong>C++20 modules</strong> with <code>import std</code>, in CMake and Bazel.</li><li><strong>Tools on clang</strong>, which link <code>libclang</code> built with PGO.</li></ul><p>xclang is developed for <a href="https://github.com/clice-io/clice" target="_blank" rel="noreferrer">clice</a>, whose release builds are its first user. <a href="https://github.com/clice-io/catter" target="_blank" rel="noreferrer">catter</a> builds with it too. xclang&#39;s CI cross-compiles the tests of <a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> for Windows from Linux and runs them on Windows.</p><h2 id="what-it-is-not" tabindex="-1">What It Is Not <a class="header-anchor" href="#what-it-is-not" aria-label="Permalink to &quot;What It Is Not&quot;">​</a></h2><ul><li><strong>C++ libraries from another toolchain need its C++ library.</strong> xclang&#39;s C++ library is <code>libc++</code>, linked into every program. A C++ library built with GCC&#39;s <code>libstdc++</code> or MSVC&#39;s STL has another ABI. Build C++ dependencies with xclang for the target, or pass <code>-stdlib=platform</code> to use the platform&#39;s C++ library and give up self-contained programs (<a href="./cross-compiling#the-platform-s-c-library">cross-compiling</a>). C libraries are not affected.</li><li><strong>One <code>libc++</code> per shared object.</strong> Each shared library carries its own <code>libc++</code>, so C++ objects should not cross shared libraries, and on Linux and macOS a standard exception thrown in one is caught in another only by <code>catch (...)</code> (<a href="./../design/hermeticity#one-libc-per-shared-object">hermeticity</a>, <a href="./../design/roadmap#shared-runtime">roadmap</a>).</li><li><strong>No OpenMP runtime, and no <code>clang-format</code>, <code>clang-tidy</code> or <code>clangd</code> programs.</strong> xclang is a compiler toolchain (<a href="./../design/roadmap#openmp">OpenMP</a>, <a href="./../design/roadmap#tool-binaries">tool binaries</a>).</li><li><strong>Not for conda-forge packages.</strong> Use conda-forge&#39;s compilers, which link its shared runtime packages through <code>run_exports</code>; xclang does not (<a href="./../design/roadmap#conda-forge">roadmap</a>).</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="./quick-start">Quick Start</a>: install xclang, build programs for every target, and build a CMake project with <code>import std</code>.</li><li><a href="./cross-compiling">Cross-Compiling</a>: targets, vendor SDKs, and platform details.</li><li><a href="./../reference/releases">Releases</a>: version tags, channels, assets, and verifying downloads.</li></ul>',16)])])}const p=a(r,[["render",n]]);export{m as __pageData,p as default};
